/**
 * @file    PduR_Types.h
 * @brief   PduR routing table types (generated by dbc2c.py).
 */
#ifndef PDUR_TYPES_H
#define PDUR_TYPES_H

#include "ComStack_Types.h"

typedef enum
{
    PDUR_DEST_COM = 0,      /* Deliver to Com_RxIndication */
    PDUR_DEST_CANIF         /* PDU gateway: forward to CanIf_Transmit */
} PduR_DestModuleType;

typedef struct
{
    PduR_DestModuleType module;
    PduIdType           pduId;   /* Com RX I-PDU id or CanIf TX L-PDU id */
} PduR_DestPduType;

/** Routing path for one PDU received from CanIf (1:n fan-out). */
typedef struct
{
    const PduR_DestPduType *dests;
    uint8                   numDests;
} PduR_RxRouteType;

/** Routing path for one PDU transmitted by Com. */
typedef struct
{
    PduIdType canIfTxPduId;
} PduR_ComTxRouteType;

/** Where to forward a TxConfirmation coming from CanIf. */
typedef struct
{
    boolean   toCom;      /* FALSE for gateway PDUs, nobody waits for them */
    PduIdType comPduId;
} PduR_TxConfRouteType;

typedef struct
{
    const PduR_RxRouteType     *rxRoutes;       /* Indexed by CanIf upperPduId */
    PduIdType                   numRxRoutes;
    const PduR_ComTxRouteType  *comTxRoutes;    /* Indexed by Com's PduR TX id */
    PduIdType                   numComTxRoutes;
    const PduR_TxConfRouteType *txConfRoutes;   /* Indexed by CanIf TX upperPduId */
    PduIdType                   numTxConfRoutes;
} PduR_PBConfigType;

#endif /* PDUR_TYPES_H */
